(function(){'use strict';const KEY='nawaf-hq-v5';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));function load(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}function save(s,emit=true){localStorage.setItem(KEY,JSON.stringify(s));if(emit)window.dispatchEvent(new CustomEvent('nawaf:state-updated'))}function seed(){const s=load();let changed=false;if(!Array.isArray(s.employees)||!s.employees.length){s.employees=[{id:'sara',name:'سارة',role:'المدير العام AI',department:'الإدارة العامة',status:'READY'},{id:'omar',name:'عمر',role:'قائد التقنية والبحث',department:'التقنية والبحث',status:'READY'},{id:'lian',name:'ليان',role:'قائدة المنتج والتجربة',department:'المنتج والتجربة',status:'READY'},{id:'noura',name:'نورة',role:'قائدة الجودة والمراجعة',department:'الجودة والمراجعة',status:'READY'}];changed=true}if(!Array.isArray(s.projects)||!s.projects.length){s.projects=[{id:'mueen',name:'مُعِين',status:'ACTIVE',phase:'جاهز للعمل',progress:0},{id:'qaddha',name:'قدّها',status:'ACTIVE',phase:'جاهز للعمل',progress:0}];changed=true}if(!Array.isArray(s.tasks)){s.tasks=[];changed=true}if(!Array.isArray(s.reports)){s.reports=[];changed=true}if(!Array.isArray(s.activity)){s.activity=[];changed=true}if(changed)save(s,false);return s}function status(v){return({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظارك',COMPLETED:'مكتمل'})[v]||v||'جاهز'}function icon(path){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>`}const icons={home:'M3 11.5 12 4l9 7.5V21h-6v-6H9v6H3z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m3-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8m10 0a4 4 0 1 0 0-8',projects:'M3 5h7l2 2h9v12H3z',tasks:'M4 12l5 5L20 6',reports:'M5 3h14v18H5zm3 4h8M8 11h8M8 15h5'};function shell(){const s=seed(),busy=s.employees.filter(e=>!['READY','IDLE'].includes(e.status)).length,done=s.tasks.filter(t=>t.status==='COMPLETED').length,waiting=s.tasks.filter(t=>t.status==='WAITING_FOR_NAWAF').length;$('#app').innerHTML=`<div class="v7"><aside class="v7-side"><div class="v7-brand"><b>NAWAF <span>HQ</span></b><small>AI COMPANY OS</small></div><nav><button class="active">${icon(icons.home)}<span>الرئيسية</span></button><button>${icon(icons.people)}<span>الموظفون</span></button><button>${icon(icons.projects)}<span>المشاريع</span></button><button>${icon(icons.tasks)}<span>المهام</span></button><button>${icon(icons.reports)}<span>التقارير</span></button></nav><div class="v7-ready">● SYSTEM READY<small>واجهة خفيفة بدون 3D</small></div></aside><main class="v7-main"><header><div><span class="v7-kicker">AI WORKFORCE COMMAND CENTER</span><h1>لوحة تشغيل الشركة</h1><p>أعط الموظفين أوامر مباشرة وتابع النتائج من مكان واحد.</p></div><div class="v7-actions"><button id="v7-new-employee">＋ موظف</button><button id="v7-company-command" class="primary">✦ توجيه الشركة</button></div></header><section class="v7-stats"><article><b>${s.employees.length}</b><span>الموظفون</span></article><article><b>${busy}</b><span>يعمل الآن</span></article><article><b>${s.tasks.length}</b><span>المهام</span></article><article><b>${done}</b><span>مكتمل</span></article><article><b>${waiting}</b><span>بانتظارك</span></article></section><section class="v7-grid"><div class="v7-card v7-wide"><div class="v7-head"><div><span class="v7-kicker">TEAM</span><h2>الموظفون</h2></div><small>اضغط على الموظف لإعطائه أمر</small></div><div class="v7-employees hq-3d-stage">${s.employees.map(e=>`<button class="v7-employee" data-employee="${esc(e.id)}"><span class="avatar">${esc((e.name||'AI').slice(0,1))}</span><div><b>${esc(e.name)}</b><small>${esc(e.role||e.department||'موظف AI')}</small></div><i class="${['WORKING','RESEARCHING','REVIEWING'].includes(e.status)?'busy':''}"></i><strong>${esc(status(e.status))}</strong></button>`).join('')}</div></div><div class="v7-card"><div class="v7-head"><h2>المشاريع</h2><a href="apps.html">إدارة التطبيقات</a></div>${s.projects.slice(0,4).map(p=>`<article class="v7-project"><div><b>${esc(p.name)}</b><small>${esc(p.phase||'جاهز للعمل')}</small></div><span>${Number(p.progress)||0}%</span>${['mueen','qaddha'].includes(p.id)?`<a href="${p.id==='mueen'?'https://mueen-islamic-app.vercel.app/':'https://qaddha.vercel.app/'}" target="_blank" rel="noopener">فتح</a>`:''}</article>`).join('')}</div></section><section class="v7-card"><div class="v7-head"><h2>آخر المهام</h2><span>${s.tasks.length} مهمة</span></div><div class="v7-tasks">${s.tasks.slice(0,10).map(t=>`<article><div><b>${esc(t.title)}</b><small>${esc((s.employees.find(e=>e.id===t.employeeId)||{}).name||'غير مسند')} • ${esc((s.projects.find(p=>p.id===t.projectId)||{}).name||'عام')}</small></div><span>${esc(status(t.status))}</span><strong>${Number(t.progress)||0}%</strong></article>`).join('')||'<p class="empty">ما فيه مهام إلى الآن.</p>'}</div></section></main></div>`;bind()}function bind(){const add=$('#v7-new-employee');if(add)add.onclick=()=>window.NawafHQV6?.newEmployee?.();const cc=$('#v7-company-command');if(cc)cc.onclick=()=>{const first=load().employees?.[0];if(first)window.NawafHQV6?.employee?.(first.id)};document.querySelectorAll('[data-employee]').forEach(b=>b.onclick=()=>window.NawafHQV6?.employee?.(b.dataset.employee))}let rerenderTimer;window.addEventListener('nawaf:state-updated',()=>{clearTimeout(rerenderTimer);rerenderTimer=setTimeout(shell,120)});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',shell);else shell();})();